# 1. Custom Model Definition
class SEBlock(nn.Module):
    def __init__(self, channels, reduction=16):
        super(SEBlock, self).__init__()
        self.fc = nn.Sequential(
            nn.AdaptiveAvgPool2d(1),
            nn.Flatten(),
            nn.Linear(channels, channels // reduction, bias=False),
            nn.ReLU(inplace=True),
            nn.Linear(channels // reduction, channels, bias=False),
            nn.Sigmoid()
        )

    def forward(self, x):
        b, c, _, _ = x.size()
        w = self.fc(x).view(b, c, 1, 1)
        return x * w

class ResNeXtSE(nn.Module):
    def __init__(self, num_classes=5, use_pretrained=True):
        super(ResNeXtSE, self).__init__()
        weights = models.ResNeXt50_32X4D_Weights.DEFAULT if use_pretrained else None
        self.backbone = models.resnext50_32x4d(weights=weights)
        in_features = self.backbone.fc.in_features
        self.backbone.fc = nn.Identity()
        self.se = SEBlock(in_features)
        self.classifier = nn.Linear(in_features, num_classes)

    def forward(self, x):
        features = self.backbone(x)
        return self.classifier(features)

# 2. Dataset Definition
class WBCDataset(Dataset):
    def __init__(self, root_dir, dataset_name, transform=None):
        self.root_dir = root_dir
        self.dataset_name = dataset_name
        self.transform = transform
        self.image_paths = []
        self.labels = []

        if os.path.exists(root_dir):
            for label_idx, class_dir in enumerate(sorted(os.listdir(root_dir))):
                class_path = os.path.join(root_dir, class_dir)
                if os.path.isdir(class_path):
                    for img_name in os.listdir(class_path):
                        if img_name.lower().endswith(('.png', '.jpg', '.jpeg', '.bmp', '.tif')):
                            self.image_paths.append(os.path.join(class_path, img_name))
                            self.labels.append(label_idx)

    def __len__(self):
        return len(self.image_paths)

    def __getitem__(self, idx):
        img_path = self.image_paths[idx]
        image = Image.open(img_path).convert('RGB')
        label = self.labels[idx]
        if self.transform:
            image = self.transform(image)
        return image, label, self.dataset_name

